import{a as e,c as t,i as n,l as r,n as i,o as a,r as o,s,t as c}from"./app-FtcyK8lR.js";var l=JSON.parse(`{"path":"/api/release-compare.html","title":"发布差异与集中发布流程","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1793083391000,"contributors":[{"name":"之旸 刘","username":"","email":"marufyurisa@outlook.com","commits":1}],"changelog":[{"hash":"a7bc7e5f74740c184e03fa5817e5e4576113490b","time":1793083391000,"email":"marufyurisa@outlook.com","author":"之旸 刘","message":"feat: integrate release workflows, managed backups and runtime fixes"}]},"filePathRelative":"api/release-compare.md"}`),u={name:`release-compare.md`};function d(c,l,u,d,f,p){let m=t(`RouteLink`);return s(),o(`div`,null,[l[3]||=i(`h1`,{id:`发布差异与集中发布流程`,tabindex:`-1`},[i(`a`,{class:`header-anchor`,href:`#发布差异与集中发布流程`},`#`),e(` 发布差异与集中发布流程`)],-1),i(`p`,null,[a(m,{to:`/api/`},{default:r(()=>[...l[0]||=[e(`返回 API 入口`,-1)]]),_:1}),l[2]||=e(` · `,-1),a(m,{to:`/api/scope-identity.html`},{default:r(()=>[...l[1]||=[e(`范围身份`,-1)]]),_:1})]),l[4]||=n(`<p>本页包含两件事：</p><ol><li><code>POST /api/v1/release/compare</code>：按 <code>comparison_mode</code> 比较“当前生效版本 → 目标版本”或任意两个已发布版本。</li><li>前端按顺序复用现有 lock/create/compare/activate 接口完成一次集中发布；后端不提供“一键发布”长事务。</li></ol><h2 id="_1-比较请求" tabindex="-1"><a class="header-anchor" href="#_1-比较请求">#</a> 1. 比较请求</h2><h3 id="active-缺省" tabindex="-1"><a class="header-anchor" href="#active-缺省">#</a> active（缺省）</h3><div class="language-http line-numbers-mode" data-highlighter="prismjs" data-ext="http"><pre><code class="language-http"><span class="line">POST /api/v1/release/compare</span>
<span class="line"><span class="token header"><span class="token header-name keyword">Content-Type</span><span class="token punctuation">:</span> <span class="token header-value">application/json</span></span></span>
<span class="line"><span class="token application-json"></span>
<span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;11111111-1111-4111-8111-111111111111&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v2&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;22222222-2222-4222-8222-222222222222&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_active_revision&quot;</span><span class="token operator">:</span> <span class="token string">&quot;3&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_active_snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;33333333-3333-4333-8333-333333333333&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;offset&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;limit&quot;</span><span class="token operator">:</span> <span class="token number">20</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>comparison_mode</code> 省略或传 <code>active</code>；显式空串或其他值返回 400 <code>RELEASE_INVALID_REQUEST</code>。</li><li><code>expected_scope_id</code>、<code>version</code>、<code>expected_snapshot_id</code>、<code>expected_active_revision</code> 必填。</li><li><code>expected_active_revision</code> 是非负十进制字符串；不要转成 JS number。</li><li>无生效版本时 <code>expected_active_snapshot_id</code> 传空串或省略，但 revision 仍必须传实际 head revision（首次通常 <code>&quot;0&quot;</code>）。</li><li>有 active 时若 <code>expected_active_snapshot_id</code> 为空或不符，返回 409 <code>RELEASE_COMPARE_BASELINE_MISMATCH</code>，不会自动补当前 active。</li><li>active 模式拒绝提交 <code>baseline_version</code> 或 <code>expected_baseline_snapshot_id</code>（即使空串也拒绝），避免混用。</li></ul><h3 id="fixed-任意两个版本" tabindex="-1"><a class="header-anchor" href="#fixed-任意两个版本">#</a> fixed（任意两个版本）</h3><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;comparison_mode&quot;</span><span class="token operator">:</span> <span class="token string">&quot;fixed&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;environment_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;prod&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;pipeline_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;main&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;11111111-1111-4111-8111-111111111111&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;baseline_version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v2&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_baseline_snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;22222222-2222-4222-8222-222222222222&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v5&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;expected_snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;55555555-5555-4555-8555-555555555555&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;offset&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;limit&quot;</span><span class="token operator">:</span> <span class="token number">20</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>表示“从 <code>baseline_version</code> 到 <code>version</code>”：before 是 baseline，after 是目标。</li><li>双方 version/snapshot 都必填，且必须是当前同一 scope 的未删除版本；不存在 404、已删除 410、snapshot 不符 409。</li><li>fixed 拒绝提交 <code>expected_active_revision</code> 或 <code>expected_active_snapshot_id</code>（即使空串也拒绝）。</li><li>fixed 不读写 head 来选择结果，因此不要求 active 存在，也不会因比较期间切换 active 而改变两侧；双方被删除或 scope 被删除后新请求仍返回 410。</li><li>交换 baseline 与 target 即可反转方向：modified/unchanged 数量不变，added 与 removed 对调，before/after 对调。同一版本与自身比较合法，返回 <code>items:[]</code> 和零变化。</li><li>fixed 结果不能直接作为发布确认依据；要切换生效时必须重新执行 active compare，并把该响应的 <code>active_revision</code> 交给 activate。</li></ul><h3 id="公共规则" tabindex="-1"><a class="header-anchor" href="#公共规则">#</a> 公共规则</h3><ul><li><code>expected_scope_id</code>、目标 <code>version</code>、<code>expected_snapshot_id</code> 在两种模式都必填。</li><li><code>offset</code> 默认 0；<code>limit</code> 缺省/0 为 20，负值或大于 100 返回 400。</li><li>只读：不创建版本、head、审计事件或比较记录，返回 <code>Cache-Control: no-store</code>。</li><li>不接受 editor、跨 scope 比较；旧 scope 返回 410。</li></ul><h2 id="_2-比较响应" tabindex="-1"><a class="header-anchor" href="#_2-比较响应">#</a> 2. 比较响应</h2><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">200</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;msg&quot;</span><span class="token operator">:</span> <span class="token string">&quot;OK&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;scope_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;comparison_mode&quot;</span><span class="token operator">:</span> <span class="token string">&quot;active&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;target&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v2&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;baseline&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;v1&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;snapshot_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;...&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;active_revision&quot;</span><span class="token operator">:</span> <span class="token string">&quot;3&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;target_is_active&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;has_changes&quot;</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;summary&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;added&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token property">&quot;modified&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token property">&quot;removed&quot;</span><span class="token operator">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token property">&quot;unchanged&quot;</span><span class="token operator">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;items&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span></span>
<span class="line">      <span class="token punctuation">{</span></span>
<span class="line">        <span class="token property">&quot;resource_key&quot;</span><span class="token operator">:</span> <span class="token string">&quot;site_title&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;change_type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;modified&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;changed_fields&quot;</span><span class="token operator">:</span> <span class="token punctuation">[</span><span class="token string">&quot;content&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;before&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;alias&quot;</span><span class="token operator">:</span> <span class="token string">&quot;site_title&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;网站标题&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;text&quot;</span><span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token property">&quot;after&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span><span class="token property">&quot;alias&quot;</span><span class="token operator">:</span> <span class="token string">&quot;site_title&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;网站标题&quot;</span><span class="token punctuation">,</span> <span class="token property">&quot;type&quot;</span><span class="token operator">:</span> <span class="token string">&quot;text&quot;</span><span class="token punctuation">}</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">]</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;total_changes&quot;</span><span class="token operator">:</span> <span class="token number">3</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;offset&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;limit&quot;</span><span class="token operator">:</span> <span class="token number">20</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;has_more&quot;</span><span class="token operator">:</span> <span class="token boolean">false</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;next_offset&quot;</span><span class="token operator">:</span> <span class="token null keyword">null</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>comparison_mode</code> 总是返回实际模式。</li><li>active 模式返回字符串 <code>active_revision</code> 和布尔 <code>target_is_active</code>；fixed 模式两者固定为 <code>null</code>，不暗示此刻哪个版本生效。</li><li>active 的 <code>baseline</code> 无生效版本时为 <code>null</code>，目标全部算 added；fixed 的 baseline 必不为 <code>null</code>。</li><li><code>items</code> 只含 added/modified/removed，不输出 unchanged；按 <code>resource_key</code> 的 UTF-8 字节序升序。</li><li>added 的 before 为 null，removed 的 after 为 null，changed_fields 为 <code>[]</code>。</li><li>modified 的 <code>changed_fields</code> 顺序固定：<code>alias</code>、<code>name</code>、<code>type</code>、<code>content</code>、<code>remark</code>、<code>is_perm</code>、<code>description</code>。</li><li>before/after 只是表格摘要（alias/name/type）；完整内容用 <code>GET /api/v1/release/detail</code> 分别读取目标与基线的版本，核对 <code>snapshot_id</code>。</li><li><code>has_more</code> 时 <code>next_offset</code> 是下一页 offset，否则为 <code>null</code>。</li><li><code>has_changes:false</code> 只表示配置与受管资源语义相同，不代表资源健康或发布成功。</li></ul><h2 id="_3-比较规则" tabindex="-1"><a class="header-anchor" href="#_3-比较规则">#</a> 3. 比较规则</h2><ul><li>比较键是 <code>(scope_id, resource_key)</code>。</li><li>不直接比较 runtime URL、payload 总 SHA 或快照内随机 asset_id。</li><li>受管引用按 <code>(sha256,size,content_type,file_name)</code> 加 query/fragment 后缀形成内部比较形式；图片重新快照但字节/名称/类型/引用后缀相同视为未变。</li><li>object/keyvalue 使用无损 JSON：对象键顺序和空白不算变化；数组顺序、数字词元（<code>1</code> 与 <code>1.0</code>）按不同处理；大整数不经过 float64。</li><li>富文本/CSS/srcset 复用现有 release 标记扫描规则。</li><li>用户普通文本与内部资源标记不会碰撞。</li><li>不读取资源字节；payload/清单摘要损坏或引用缺清单时整体返回 503，不返回部分差异。</li></ul><h2 id="_4-错误" tabindex="-1"><a class="header-anchor" href="#_4-错误">#</a> 4. 错误</h2><table><thead><tr><th>HTTP</th><th>error_type</th><th>说明</th></tr></thead><tbody><tr><td>400</td><td><code>RELEASE_INVALID_REQUEST</code> / <code>SCOPE_INVALID_REQUEST</code></td><td>字段、分页、revision 或身份非法</td></tr><tr><td>401/403</td><td>既有 AUTH 错误</td><td>会话、CSRF、Origin 不满足</td></tr><tr><td>404</td><td><code>RELEASE_VERSION_NOT_FOUND</code> / 范围不存在</td><td>目标/基准或范围不存在；fixed 错误带 \`side:baseline</td></tr><tr><td>409/410</td><td><code>SCOPE_IDENTITY_CONFLICT</code> / <code>SCOPE_DELETED</code></td><td>同名重建或已删除</td></tr><tr><td>410</td><td><code>RELEASE_VERSION_DELETED</code></td><td>目标或固定的基准版本已删除；fixed 错误带 <code>side</code></td></tr><tr><td>409</td><td><code>RELEASE_SNAPSHOT_MISMATCH</code></td><td>version 与 snapshot 不匹配；fixed 错误带 <code>side</code></td></tr><tr><td>409</td><td><code>RELEASE_ACTIVE_REVISION_CONFLICT</code></td><td>head revision 不符，返回 <code>latest_active</code>（无 active 时 null）</td></tr><tr><td>409</td><td><code>RELEASE_COMPARE_BASELINE_MISMATCH</code></td><td>revision 相同但 active snapshot 不符</td></tr><tr><td>503</td><td><code>RELEASE_INCOMPLETE</code></td><td>payload/清单损坏或引用缺清单</td></tr><tr><td>503</td><td><code>RELEASE_COMPARE_TIMEOUT</code></td><td>计算超时，可按原参数重试</td></tr></tbody></table><h2 id="_5-集中发布流程" tabindex="-1"><a class="header-anchor" href="#_5-集中发布流程">#</a> 5. 集中发布流程</h2><table><thead><tr><th>步骤</th><th>接口</th><th>客户端固定</th></tr></thead><tbody><tr><td>读取状态</td><td>环境/渠道、<code>GET freeze/status</code>、<code>GET release/active</code></td><td>当前 <code>scope_id</code>、freeze revision、active snapshot 和始终存在的 <code>data.active_revision</code></td></tr><tr><td>锁版</td><td><code>POST freeze/lock</code></td><td><code>expected_scope_id</code>、<code>expected_revision</code></td></tr><tr><td>创建候选</td><td><code>POST release/create</code></td><td>同一 scope、锁版后的 freeze revision、独立 create request_id；不提交 version，使用响应中的实际编号</td></tr><tr><td>查看差异</td><td><code>POST release/compare</code></td><td>目标 version/snapshot、比较时 active snapshot/revision</td></tr><tr><td>确认生效</td><td><code>POST release/activate</code></td><td>同一 scope、目标 version、compare 返回的 active_revision、独立 activate request_id</td></tr><tr><td>核对</td><td><code>GET release/active</code> / <code>release/detail</code></td><td>原请求与目标身份；区分“操作曾成功”和“此刻仍生效”</td></tr></tbody></table><ul><li>已锁范围直接使用当前 freeze revision 创建，不重复锁版。</li><li>已有未生效版本可直接 compare → activate，无需重新创建。</li><li>首次无 active 可发布：compare 与空基准比较，activate 使用 <code>GET release/active</code> 返回的 <code>data.active_revision</code> 字符串；不能因为 <code>active:null</code> 就假设 revision 一定是 0。</li><li><code>active_revision</code> 非零但 <code>active:null</code> 是兼容边界状态，当前没有正常公开入口主动制造；遇到时应按真实 revision 做 compare/activate，必要时由管理员核对，不要重置 revision 或自动加一。</li><li>create 与 activate 使用两个独立 request_id；响应丢失时原样重放。自动编号在 create 事务内分配，重放不会再次消耗编号。</li><li>发布确认只能使用 active compare；fixed compare 的 <code>active_revision</code> 为 null，不能拿来静默切换。</li><li>compare 后 active 被其他人切换：activate 用旧 revision 返回 409；重新调用 <code>release/active</code> 取得新 <code>active_revision</code>，重新 compare，再由用户确认。不能先刷新 head 静默切换，也不能从错误文字提取数字自动重试。</li><li>activate 不要求 compare 令牌；服务端仍校验 scope、目标未删和 revision CAS。</li><li>取消或切换失败：候选版本保留且未生效，active 不变；可继续 compare 或显式删除版本。</li><li>冻结后取消整个流程不自动解锁；用户可显式 unlock。</li><li>当前 scope 被删除重建后，旧流程终止，不迁移候选、revision 或 request_id。</li></ul><h2 id="_6-维护与鉴权" tabindex="-1"><a class="header-anchor" href="#_6-维护与鉴权">#</a> 6. 维护与鉴权</h2><ul><li>compare 是只读 POST，但仍要求管理员会话与 CSRF/Origin；不在公开 runtime 白名单。</li><li>备份维护期间 compare 可用；lock/create/activate 等写接口仍受原维护保护返回 503。</li><li>比较不占用全局业务写闸门，不阻塞用户直到确认。</li><li>单次请求最长 60 秒，沿用每快照 5000 配置/64 MiB payload 上限。</li></ul>`,23)])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};